 "content": "def transform(grid):
    """Composite four 3x6 color layers using the precedence 5 > 4 > 8 > 2."""
    if len(grid) != 12 or any(len(row) != 6 for row in grid):
        raise ValueError("expected a 12x6 grid")
    priority = (5, 4, 8, 2)
    out = []
    for r in range(3):
        row = []
        for c in range(6):
            values = {grid[layer * 3 + r][c] for layer in range(4)}
            row.append(next((color for color in priority if color in values), 0))
        out.append(row)
    return out
